fn place(arr: Vec<f32>, mask: Vec<bool>, vals: Vec<f32>) -> Vec<f32> {
    // Precondition checks
    assert_eq!(arr.len(), mask.len(), "arr and mask must have the same length");
    assert!(!vals.is_empty(), "vals must be non-empty");

    let mut result = Vec::with_capacity(arr.len());
    let mut vals_idx = 0;
    let vals_len = vals.len();

    for (a, &m) in arr.into_iter().zip(mask.iter()) {
        if m {
            // Use the next replacement value, cycling when we reach the end
            result.push(vals[vals_idx]);
            vals_idx = (vals_idx + 1) % vals_len;
        } else {
            // Preserve the original value
            result.push(a);
        }
    }

    result
}

